const $=id=>document.getElementById(id);
let me=null,currentPage='dashboard',selectedStudentId=null,attendanceClassId='',attendanceDate=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'}),sfpsClassesCache=null,activeController=null;
const CLASS_ORDER={LKG:1,NUR:2,UKG:3,'1':4,'2':5,'3':6,'4':7,'5':8,'6':9,'7':10,'8':11,'9':12,'10':13};
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
async function api(url,opt={}){const options={credentials:'include',...opt};if(!options.signal&&activeController)options.signal=activeController.signal;const r=await fetch(url,options);let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||`Request failed (${r.status})`);return d}
function setTitle(t,s=''){ $('welcome').textContent=t;$('pageSubtitle').textContent=s; }
function classOptions(classes,selected='',includeAll=true){return (includeAll?'<option value="">All classes</option>':'<option value="">Select class</option>')+(classes||[]).map(c=>`<option value="${c.id}" ${String(selected)===String(c.id)?'selected':''}>${esc(c.name)}</option>`).join('')}
async function getSFPSClasses(){if(sfpsClassesCache)return sfpsClassesCache;const d=await api('/api/dashboard/classes');sfpsClassesCache=(d.classes||[]).sort((a,b)=>(CLASS_ORDER[a.name]||99)-(CLASS_ORDER[b.name]||99));return sfpsClassesCache}
async function linkedStudentSelector(){if(me.role!=='parent')return '';const d=await api('/api/students');const ss=d.students||[];if(!selectedStudentId&&ss[0])selectedStudentId=ss[0].id;return `<label class="student-switch">Student<select onchange="selectLinkedStudent(this.value)"><option value="">Select student</option>${ss.map(s=>`<option value="${s.id}" ${String(selectedStudentId)===String(s.id)?'selected':''}>${esc(s.student_uid)} · ${esc(s.name)} · ${esc(s.class_name||'')}</option>`).join('')}</select></label>`}
function nav(){const items=[['dashboard','Dashboard'],['students','Students'],['teachers','Teachers'],['attendance','Attendance'],['syllabus','Syllabus'],['diary','Teacher Diary'],['results','Results'],['fees','Fees'],['parent','Parent Accounts'],['parentIds','Parent IDs'],['headTeach','Head Teach'],['attendanceControl','Attendance Control'],['seatPlanner','Seat Planning'],['developerConsole','Developer Console'],['parentNotices','Notices'],['ratings','Teacher Ratings']];const role=String(me.role);const owner=Boolean(me.is_developer);const visible=items.filter(([k])=>{if(k==='teachers')return ['owner','sub-owner','manager'].includes(role);if(k==='parent')return ['owner','sub-owner','manager','parent'].includes(role);if(k==='parentIds')return owner;if(k==='headTeach')return role==='teacher';if(k==='attendanceControl')return ['owner','sub-owner','manager'].includes(role);if(k==='seatPlanner')return Boolean(me.is_ajeet)||owner;if(k==='developerConsole')return owner;if(k==='parentNotices'||k==='ratings')return role==='parent';if(role==='teacher')return ['dashboard','students','attendance','syllabus','diary','headTeach'].includes(k);if(role==='student')return ['dashboard','attendance','syllabus','diary','results'].includes(k);if(role==='parent')return ['dashboard','students','attendance','syllabus','diary','results','fees','parent'].includes(k);return true});
$('nav').innerHTML='<div class="nav-group">Main</div>'+visible.map(([k,l])=>`<button class="nav-btn" data-page="${k}"><span class="nav-icon">${({dashboard:'⌂',students:'♙',teachers:'♟',attendance:'✓',syllabus:'▤',diary:'▣',results:'▥',fees:'₹',parent:'♧',headTeach:'⌘',attendanceControl:'⚙',seatPlanner:'◈',developerConsole:'⌘',parentIds:'♧'})[k]||'•'}</span>${l}</button>`).join('')+'<div class="nav-group" style="margin-top:14px">Tools</div><button class="nav-btn" data-page="yt"><span class="nav-icon">✦</span>YT · Your Teacher</button>';
$('nav').querySelectorAll('.nav-btn').forEach(b=>b.onclick=()=>{show(b.dataset.page);$('sidebar')?.classList.remove('open')})}
function cards(obj){const meta={students:['Students','♙'],teachers:['Teachers','♟'],classes:['Classes','▤'],announcements:['Notices','✦']};$('cards').innerHTML=Object.entries(obj||{}).map(([k,v])=>`<div class="card"><div class="card-top"><span>${meta[k]?.[0]||esc(k)}</span><div class="card-icon">${meta[k]?.[1]||'•'}</div></div><strong>${esc(v)}</strong></div>`).join('')}
function renderError(page,e){console.error(page,e);$('cards').innerHTML='';$('tableArea').innerHTML=`<div class="module-card module-error"><div class="module-error-icon">!</div><div><h2>${esc(page)} could not be loaded</h2><p>${esc(e.message||e)}</p><button class="primary" onclick="show('${esc(page)}')">Retry</button></div></div>`;$('announcements').innerHTML='<div class="notice"><b>SFPS</b><div>Please retry this section.</div></div>'}
async function dashboard(){setTitle('Dashboard','Your school at a glance');const d=await api('/api/dashboard/summary');cards(d.cards);$('tableArea').innerHTML=`<div class="panel-head"><div><h2>Welcome to Stanford Public School</h2><p>Everything you are allowed to access is available from the left navigation.</p></div></div><div class="population-grid">${(d.recentStudents||[]).map(s=>`<div class="population-card"><span>${esc(s.class_name||'Student')}</span><strong>${esc(s.name)}</strong><small>${esc(s.student_uid)}</small></div>`).join('')||'<div class="empty">No student records yet.</div>'}</div>`;$('announcements').innerHTML=(d.recentAnnouncements||[]).map(a=>`<div class="notice"><b>${esc(a.title)}</b><small>${esc(a.created_at||'')}</small><div>${esc(a.message)}</div></div>`).join('')||'<div class="empty">No notices.</div>'}
async function students(){setTitle('Students','Student registry and class records');const [d,classes]=await Promise.all([api('/api/students'),getSFPSClasses()]);const canAdd=['owner','sub-owner','manager','teacher'].includes(me.role);cards({students:(d.students||[]).length,classes:classes.length});$('tableArea').innerHTML=`<div class="panel-head"><div><h2>Student Registry</h2><p>Student records are filtered by your account permissions.</p></div><div class="toolbar">${canAdd?'<button class="primary" onclick="addStudentAdmin()">+ Add Student</button>':''}<label class="student-switch">Class<select onchange="filterTableClass(this.value)">${classOptions(classes,'',true)}</select></label></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>ID</th><th>Class</th><th>Roll</th><th>Parent</th></tr></thead><tbody>${(d.students||[]).map(s=>`<tr data-class-row="${s.class_id}"><td><strong>${esc(s.name)}</strong></td><td>${esc(s.student_uid)}</td><td>${esc(s.class_name||'')}</td><td>${esc(s.roll_no??'—')}</td><td>${esc(s.parent_name||'—')}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">No students found.</div></td></tr>'}</tbody></table></div>`;$('announcements').innerHTML='<div class="notice"><b>Student records</b><div>Parents see only students linked to their account.</div></div>'}
function filterTableClass(v){document.querySelectorAll('[data-class-row]').forEach(r=>r.hidden=!!v&&String(r.dataset.classRow)!==String(v))}
async function teachers(){setTitle('Teachers','Staff directory and work access');const d=await api('/api/teachers');cards({teachers:(d.teachers||[]).length});$('tableArea').innerHTML=`<div class="panel-head"><div><h2>Staff Directory</h2><p>Titles are derived from the User ID suffix.</p></div>${['owner','sub-owner','manager'].includes(me.role)?'<button class="primary" onclick="createStaff()">+ Add Teacher</button>':''}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Name</th><th>Role</th><th>Category</th><th>Work</th></tr></thead><tbody>${(d.teachers||[]).map(t=>`<tr><td><strong>${esc(t.display_name||t.name)}</strong></td><td>${esc(t.role)}</td><td>${esc(t.category||'')}</td><td>${esc(t.work||'')}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">No teachers.</div></td></tr>'}</tbody></table></div>`;$('announcements').innerHTML='<div class="notice"><b>Staff directory</b><div>Protected account controls are available only to authorized administrators.</div></div>'}
async function attendance(){setTitle('Attendance','Student attendance register and daily history');const [d,classes]=await Promise.all([api('/api/academic/attendance?date='+encodeURIComponent(attendanceDate)+(attendanceClassId?'&classId='+encodeURIComponent(attendanceClassId):'')),getSFPSClasses()]);const canMark=['owner','sub-owner','manager','teacher'].includes(me.role);const closed=!!d.closed;const rows=d.attendance||[];cards({students:rows.length,present:rows.filter(x=>x.status==='present').length,absent:rows.filter(x=>x.status==='absent').length,date:attendanceDate});$('tableArea').innerHTML=`<div class="panel-head"><div><h2>Daily Student Register</h2><p>${closed?'Attendance is closed for this date.':'Present is saved immediately with the date in history.'}</p></div><div class="toolbar"><label class="student-switch">Date<input type="date" value="${esc(attendanceDate)}" onchange="attendanceDate=this.value;attendance()"></label><label class="student-switch">Class<select onchange="attendanceClassId=this.value;attendance()">${classOptions(classes,attendanceClassId,true)}</select></label><button class="secondary" onclick="attendanceHistory()">History</button></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>Class</th><th>Status</th><th>Present</th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${esc(x.name)}</strong><small class="table-sub">${esc(x.student_uid)}${x.roll_no?' · Roll '+esc(x.roll_no):''}</small></td><td>${esc(x.class_name||'')}</td><td>${x.status?`<span class="pill ${x.status==='present'?'green':x.status==='absent'?'red':''}">${esc(x.status)}</span>`:'<span class="pill">Not marked</span>'}</td><td>${canMark&&!closed?`<label class="attendance-check"><input type="checkbox" ${x.status==='present'?'checked':''} onchange="saveStudentAttendance(${x.student_id},this.checked?'present':'absent','${attendanceDate}')"><span>Present</span></label>`:'—'}</td></tr>`).join('')||'<tr><td colspan="4"><div class="empty">No students available.</div></td></tr>'}</tbody></table></div>`;let registryHtml='';
 if(['teacher','manager'].includes(me.role)){
   const tr=await api('/api/academic/teacher-registry?date='+encodeURIComponent(attendanceDate));
   registryHtml=`<div class="planner-prompt"><h3>Teacher Registry</h3><p>${tr.enabled?'Registry is enabled for today.':'Registry is waiting for owner authorization.'}</p><button class="primary" onclick="requestTeacherCheckIn()" ${tr.enabled&&!tr.closed?'':'disabled'}>${tr.registry?.some(x=>Number(x.user_id||x.teacher_id)===Number(me.id)&&x.check_in)?'Checked in today':'Check in at school'}</button></div>`;
 }
 $('tableArea').innerHTML+=registryHtml;
 $('announcements').innerHTML=`<div class="notice"><b>Attendance</b><div>${esc(d.closureReason||'Attendance is active according to school rules.')}</div></div>`}
async function requestTeacherCheckIn(){
 if(!navigator.geolocation){alert('Location services are not available on this device.');return}
 navigator.geolocation.getCurrentPosition(async pos=>{try{await api('/api/academic/teacher-registry/check-in',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({latitude:pos.coords.latitude,longitude:pos.coords.longitude})});await attendance()}catch(e){alert(e.message)}},()=>alert('SFPS needs your location to verify that you are at school.'),{enableHighAccuracy:true,timeout:10000,maximumAge:0});
}
async function saveStudentAttendance(studentId,status,date){try{await api('/api/academic/attendance',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({studentId,status,date})});await attendance()}catch(e){alert(e.message);await attendance()}}
async function attendanceHistory(){const q=selectedStudentId?'?studentId='+selectedStudentId:'';const d=await api('/api/academic/attendance/history'+q);$('cards').innerHTML='';$('tableArea').innerHTML=`<div class="panel-head"><div><h2>Attendance History</h2><p>Every change is retained with its date.</p></div><button class="secondary" onclick="attendance()">Back</button></div><div class="table-wrap"><table class="data-table"><tr><th>Date</th><th>Student</th><th>Class</th><th>Old</th><th>New</th><th>Changed</th></tr>${(d.history||[]).map(x=>`<tr><td>${esc(x.attendance_date)}</td><td>${esc(x.student_id)}</td><td>${esc(x.class_id)}</td><td>${esc(x.old_status||'—')}</td><td>${esc(x.new_status)}</td><td>${esc(x.changed_at)}</td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">No history yet.</div></td></tr>'}</table></div>`}
async function teacherDiary(){setTitle('Teacher Diary','Class, period, C.W. and H.W. by date');const classes=await getSFPSClasses();const selector=await linkedStudentSelector();const q=me.role==='parent'&&selectedStudentId?'?studentId='+selectedStudentId:(me.role==='student'?'':'');const d=await api('/api/academic/diary'+q);const canWrite=['owner','sub-owner','manager','teacher'].includes(me.role);const ownClasses=me.role==='teacher'?(await api('/api/teachers/my-classes')).classes||[]:classes;cards({records:(d.diary||[]).length,classes:13});let form='';if(canWrite)form=`<div class="planner-prompt"><div class="prompt-head"><div><span class="prompt-icon">▣</span><div><h3>New diary entry</h3><p>Use the real SFPS class dropdown.</p></div></div></div><div class="form-grid"><label>Class<select id="diaryClass">${(ownClasses||[]).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>Subject<input id="diarySubject" placeholder="Subject"></label><label>Period<select id="diaryPeriod">${Array.from({length:8},(_,i)=>`<option value="${i+1}">Period ${i+1}</option>`).join('')}</select></label><label>Date<input id="diaryDate" type="date" value="${esc(attendanceDate)}"></label></div><label>C.W. (Written)<textarea id="diaryCW" rows="3" placeholder="What was written/taught in class?"></textarea><label>H.W. (Written)<textarea id="diaryHW" rows="3" placeholder="Homework written for students"></textarea><label>Students who did not make H.W.<input id="diaryNoHW" placeholder="Names / rolls, e.g. Rohan (4), Aman (9)"></label><button class="primary" onclick="saveDiary()">Save Diary</button></div>`;$('tableArea').innerHTML=selector+form+`<div class="panel-head"><div><h2>Diary history</h2><p>Full class diary is available to the linked parent/student according to access.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Class</th><th>Period</th><th>Subject</th><th>C.W.</th><th>H.W.</th><th>H.W. not made</th></tr></thead><tbody>${(d.diary||[]).map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.class_name)}</td><td>${esc(x.period)}</td><td>${esc(x.subject)}</td><td>${esc(x.cw_written)}</td><td>${esc(x.hw_written)}</td><td>${esc(x.notes||'—')}</td></tr>`).join('')||'<tr><td colspan="7"><div class="empty">No diary entries.</div></td></tr>'}</tbody></table></div>`;$('announcements').innerHTML='<div class="notice"><b>Teacher Diary</b><div>Parents and students can view the diary of their linked class.</div></div>'}
async function saveDiary(){try{await api('/api/academic/diary',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({classId:$('diaryClass').value,date:$('diaryDate').value,period:$('diaryPeriod').value,subject:$('diarySubject').value,cwWritten:$('diaryCW').value,hwWritten:$('diaryHW').value,notes:$('diaryNoHW').value})});await teacherDiary()}catch(e){alert(e.message)}}
async function syllabus(){
 setTitle('Syllabus','Annual syllabus and SFPS academic periods');
 const [d,p,classes]=await Promise.all([api('/api/academic/syllabus'),api('/api/academic/periods'),getSFPSClasses()]);
 const periods=p.periods||[]; let form='';
 if(me.role==='teacher'){
   const mine=(await api('/api/teachers/my-classes')).classes||[], ids=new Set(mine.map(x=>Number(x.id)));
   form=`<div class="planner-prompt"><h3>Create syllabus</h3><div class="form-grid"><label>Class<select id="syClass">${classes.map(c=>`<option value="${c.id}" ${ids.has(Number(c.id))?'':'disabled'}>${esc(c.name)}${ids.has(Number(c.id))?'':' · Not assigned'}</option>`).join('')}</select></label><label>Subject<input id="sySubject" placeholder="Mathematics"></label><label>Total Chapters<input id="syTotal" type="number" min="1"></label><label>Chapters Taught<input id="syTaught" type="number" min="0" value="0"></label></div><div class="sy-period-grid">${periods.map(x=>`<label class="sy-period-card"><span>${esc(x.name)}</span><input class="sy-period-input" data-period="${x.code}" type="number" min="0" value="0"><small>${x.remaining_days==null?'Dates not set':x.remaining_days+' days remaining'}</small></label>`).join('')}</div><textarea id="syDetails" rows="3" placeholder="Learning objectives, chapter names, topics, practicals, activities..."></textarea><input id="syNote" placeholder="Completion / progress note"><button class="primary" onclick="saveSyllabusPlan()">Save Complete Syllabus</button></div><div class="planner-prompt"><h3>My Teaching Classes</h3><p>Multi-select all classes you teach.</p><select id="myTeachingClasses" multiple size="8">${classes.map(c=>`<option value="${c.id}" ${ids.has(Number(c.id))?'selected':''}>${esc(c.name)}</option>`).join('')}</select><button class="secondary" onclick="saveMyTeachingClasses()">Save my classes</button></div>`;
 } else if(['owner','sub-owner','manager'].includes(me.role)){
   form=`<div class="planner-prompt"><h3>Create / manage syllabus</h3><p>Administrators can create syllabus records for any SFPS class.</p><div class="form-grid"><label>Class<select id="syClass">${classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>Subject<input id="sySubject" placeholder="Mathematics"></label><label>Total Chapters<input id="syTotal" type="number" min="1"></label><label>Chapters Taught<input id="syTaught" type="number" min="0" value="0"></label></div><div class="sy-period-grid">${periods.map(x=>`<label class="sy-period-card"><span>${esc(x.name)}</span><input class="sy-period-input" data-period="${x.code}" type="number" min="0" value="0"><small>${x.remaining_days==null?'Dates not set':x.remaining_days+' days remaining'}</small></label>`).join('')}</div><textarea id="syDetails" rows="3" placeholder="Syllabus details"></textarea><input id="syNote" placeholder="Completion / progress note"><button class="primary" onclick="saveSyllabusPlan()">Save Syllabus</button></div><div class="planner-prompt"><h3>Exam Time Periods</h3><div class="sy-calendar-grid">${periods.map(x=>`<div class="sy-calendar-row"><strong>${esc(x.name)}</strong><label>Start<input class="period-start" data-code="${x.code}" type="date" value="${x.start_date||''}"></label><label>End<input class="period-end" data-code="${x.code}" type="date" value="${x.end_date||''}"></label></div>`).join('')}</div><button class="secondary" onclick="saveAcademicPeriods()">Save Exam Periods</button></div>`;
 } else if(me.role==='parent') form=await linkedStudentSelector();
 else if(me.role==='student') form='';
 const rows=d.syllabus||[];cards({planned:rows.reduce((n,x)=>n+x.total_chapters,0),taught:rows.reduce((n,x)=>n+x.chapters_taught,0),remaining:rows.reduce((n,x)=>n+x.chapters_remaining,0),records:rows.length});
 $('tableArea').innerHTML=form+`<div class="panel-head"><div><h2>Syllabus records</h2><p>Periodic 1 · Periodic 2 · Term 1 · Periodic 3 · Periodic 4 · Term 2 (Final)</p></div></div><div class="table-wrap"><table class="data-table"><tr><th>Class</th><th>Subject</th><th>Total</th><th>Taught</th><th>Remaining</th><th>Progress</th></tr>${rows.map(x=>`<tr><td>${esc(x.class_name)}</td><td>${esc(x.subject)}</td><td>${x.total_chapters}</td><td>${x.chapters_taught}</td><td>${x.chapters_remaining}</td><td>${x.progress_percent}%</td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">No syllabus records.</div></td></tr>'}</table></div>`;
 $('announcements').innerHTML='<div class="notice"><b>SFPS Academic Sequence</b><div>Periodic 1, Periodic 2, Term 1, Periodic 3, Periodic 4 and Term 2 (Final).</div></div>';
}
async function saveSyllabusPlan(){const by={};document.querySelectorAll('.sy-period-input').forEach(i=>by[i.dataset.period]=Number(i.value)||0);try{await api('/api/academic/syllabus',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({classId:$('syClass').value,subject:$('sySubject').value,totalChapters:$('syTotal').value,chaptersTaught:$('syTaught').value,chaptersByPeriod:by,details:$('syDetails').value,completionNote:$('syNote').value})});await syllabus()}catch(e){alert(e.message)}}
async function saveMyTeachingClasses(){const ids=[...$('myTeachingClasses').selectedOptions].map(o=>Number(o.value));try{await api('/api/teachers/my-classes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({classIds:ids})});alert('Teaching classes saved.');await syllabus()}catch(e){alert(e.message)}}
async function saveAcademicPeriods(){const codes=[...document.querySelectorAll('.period-start')].map(x=>x.dataset.code);const periods=codes.map(code=>({code,startDate:document.querySelector(`.period-start[data-code="${code}"]`).value||null,endDate:document.querySelector(`.period-end[data-code="${code}"]`).value||null}));try{await api('/api/academic/periods',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({periods})});await syllabus()}catch(e){alert(e.message)}}
async function headTeach(){setTitle('Head Teach','Teachers choose and change their Class Teacher assignment');const d=await api('/api/teachers/head-teach');cards({classes:13,assigned:(d.classes||[]).filter(x=>x.isMine).length});$('tableArea').innerHTML=`<div class="planner-prompt"><h2>Choose your Class Teacher class</h2><p>Only a teacher can make this selection. Owners and managers cannot self-select as Class Teacher.</p><label>Class<select id="headClass">${d.classes.filter(x=>x.assigned).map(c=>`<option value="${c.id}" ${c.isMine?'selected':''}>${esc(c.name)}${c.classTeacher?' · '+esc(c.classTeacher.name):''}</option>`).join('')||'<option value="">No teaching class assigned</option>'}</select></label><button class="primary" onclick="saveHeadTeach()">Set as My Class</button></div><div class="table-wrap"><table class="data-table"><tr><th>Class</th><th>Current Class Teacher</th><th>Status</th></tr>${d.classes.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.classTeacher?.name||'Not assigned')}</td><td>${c.isMine?'You are Class Teacher':c.assigned?'You teach this class':'Not assigned to you'}</td></tr>`).join('')}</table></div>`;$('announcements').innerHTML='<div class="notice"><b>Head Teach</b><div>Your selection is limited to classes you teach.</div></div>'}
async function saveHeadTeach(){try{await api('/api/teachers/head-teach',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({classId:$('headClass').value})});await headTeach()}catch(e){alert(e.message)}}
async function results(){
 setTitle('Results','Student result reports by class');
 const selector=await linkedStudentSelector();
 const [d,sd]=await Promise.all([api('/api/academic/results'+(selectedStudentId?'?studentId='+selectedStudentId:'')),api('/api/students')]);
 const rows=d.results||[];
 const studentRows=sd.students||[];
 const canApply=['teacher','manager','owner','sub-owner'].includes(String(me.role).toLowerCase());
 const classMap=new Map();
 studentRows.forEach(st=>{const key=String(st.class_id||'');if(!classMap.has(key))classMap.set(key,{id:key,name:st.class_name||'Class',students:new Map()});const g=classMap.get(key);g.students.set(Number(st.id),{id:Number(st.id),name:st.name||'Student',class_name:st.class_name||'',results:[]})});
 rows.forEach(r=>{const key=String(r.class_id||'');if(!classMap.has(key))classMap.set(key,{id:key,name:r.class_name||'Class',students:new Map()});const g=classMap.get(key);const sid=Number(r.student_id);if(!g.students.has(sid))g.students.set(sid,{id:sid,name:r.name||'Student',class_name:r.class_name||'',results:[]});g.students.get(sid).results.push(r)});
 const allClasses=await getSFPSClasses();
 allClasses.forEach(c=>{const key=String(c.id);if(!classMap.has(key))classMap.set(key,{id:key,name:c.name,students:new Map()});else classMap.get(key).name=c.name});
 const sections=allClasses.map(c=>{const g=classMap.get(String(c.id));const students=[...(g?.students.values()||[])].sort((a,b)=>a.name.localeCompare(b.name));return `<section class="result-class-section"><div class="result-class-head"><div><span class="eyebrow">Class</span><h2>${esc(c.name)}</h2></div><span class="result-count">${students.length} student${students.length===1?'':'s'}</span></div><div class="result-student-grid">${students.map(st=>`<button type="button" class="result-student-card" onclick="openStudentResult(${st.id})"><span class="result-student-avatar">${esc((st.name||'S').slice(0,1).toUpperCase())}</span><span><strong>${esc(st.name)}</strong><small>View result report</small></span><span class="result-arrow">›</span></button>`).join('')||'<div class="empty">No result published for this class yet.</div>'}</div></section>`}).join('');
 const apply=canApply?`<div class="results-apply-bar"><button class="primary" type="button" onclick="openResultCreateModal()">Apply</button></div>`:'';
 $('cards').innerHTML='';
 $('tableArea').innerHTML=selector+`<div class="results-intro"><div><h2>Examination Results</h2><p>Choose a student to view the complete published report.</p></div></div>${sections}${apply}`;
 $('announcements').innerHTML='<div class="notice"><b>Result reports</b><div>Student result details are available according to account permissions.</div></div>';
}
async function openStudentResult(studentId){try{const d=await api('/api/academic/results?studentId='+encodeURIComponent(studentId));const rows=d.results||[];if(!rows.length){return openSimpleModal('Result Report','<div class="empty">No result has been published for this student yet.</div>','<button class="primary" type="button" onclick="closeSFPSModal()">Close</button>')}const first=rows[0];const total=rows.reduce((n,x)=>n+Number(x.max_marks||0),0);const obtained=rows.reduce((n,x)=>n+Number(x.marks||0),0);const pct=total?((obtained/total)*100).toFixed(2):'0.00';const grade=rows[0].grade||gradeFromPercentage(Number(pct));const subjectRows=rows.map(x=>`<tr><td>${esc(x.subject)}</td><td>${Number(x.max_marks||0)}</td><td>${Number(x.marks||0)}</td><td>${Number(x.max_marks||0)?((Number(x.marks||0)/Number(x.max_marks||0))*100).toFixed(2)+'%':'0%'}</td></tr>`).join('');openSimpleModal('Result Report',`<div class="result-report"><div class="result-report-title"><div><h3>${esc(first.name)}</h3><p>${esc(first.class_name||'')} · ${esc(first.exam_name||'Examination')}</p></div><div class="result-grade"><strong>${esc(grade)}</strong><small>Grade</small></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Subject</th><th>Full Marks</th><th>Obtained</th><th>Percentage</th></tr></thead><tbody>${subjectRows}</tbody></table></div><div class="result-summary"><div><span>Total Marks</span><strong>${total}</strong></div><div><span>Total Obtained</span><strong>${obtained}</strong></div><div><span>Percentage</span><strong>${pct}%</strong></div><div><span>Grade</span><strong>${esc(grade)}</strong></div></div></div>`,'<button class="primary" type="button" onclick="closeSFPSModal()">Close</button>')}catch(e){alert(e.message)}}
function gradeFromPercentage(p){if(p>=90)return'A+';if(p>=80)return'A';if(p>=70)return'B+';if(p>=60)return'B';if(p>=50)return'C';if(p>=40)return'D';return'E'}
function openResultCreateModal(){const classes=sfpsClassesCache||[];const cls=classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');openSimpleModal('Create Student Result',`<form id="resultCreateForm"><div class="form-grid"><label>Class<select id="resultClass" required onchange="loadResultStudents()">${cls}</select></label><label>Student<select id="resultStudent" required></select></label><label>Exam / Period<select id="resultExam" required><option>Periodic 1</option><option>Periodic 2</option><option>Term 1</option><option>Periodic 3</option><option>Periodic 4</option><option>Term 2 (Final)</option></select></label><label>Exam Date<input id="resultDate" type="date" value="${attendanceDate}"></label></div><div id="resultSubjects"></div><button class="secondary" type="button" onclick="addResultSubject()">+ Add Subject</button><div id="resultCreateStatus" class="modal-status"></div></form>`,'<button class="secondary" type="button" onclick="closeSFPSModal()">Cancel</button><button class="primary" type="button" onclick="submitResult()">Save Result</button>');loadResultStudents();addResultSubject()}
async function loadResultStudents(){const cls=$('resultClass')?.value;if(!cls)return;try{const d=await api('/api/students?classId='+encodeURIComponent(cls));const list=(d.students||[]);$('resultStudent').innerHTML=list.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')||'<option value="">No students</option>'}catch(e){if($('resultCreateStatus'))$('resultCreateStatus').textContent=e.message}}
function addResultSubject(){const box=$('resultSubjects');if(!box)return;const i=box.querySelectorAll('.result-subject-row').length+1;const row=document.createElement('div');row.className='result-subject-row';row.innerHTML=`<label>Subject ${i}<input class="result-subject" placeholder="Subject name" required></label><label>Full Marks<input class="result-max" type="number" min="1" step="0.01" value="100" required></label><label>Obtained Marks<input class="result-obtained" type="number" min="0" step="0.01" value="0" required></label><button class="danger" type="button" onclick="this.parentElement.remove()">Remove</button>`;box.appendChild(row)}
async function submitResult(){const studentId=$('resultStudent')?.value;const examName=$('resultExam')?.value;const rows=[...document.querySelectorAll('.result-subject-row')].map(r=>({subject:r.querySelector('.result-subject').value.trim(),maxMarks:Number(r.querySelector('.result-max').value),marks:Number(r.querySelector('.result-obtained').value)}));if(!studentId||!examName||!rows.length||rows.some(x=>!x.subject||x.maxMarks<=0||x.marks<0||x.marks>x.maxMarks)){return alert('Enter a valid student, exam and subject marks.')}try{await api('/api/academic/results',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({studentId,examName,examDate:$('resultDate').value,subjects:rows})});closeSFPSModal();await results()}catch(e){if($('resultCreateStatus'))$('resultCreateStatus').textContent=e.message;else alert(e.message)}}
function openSimpleModal(title,body,actions){closeSFPSModal();const m=document.createElement('div');m.id='sfpsModal';m.className='sfps-modal-backdrop';m.innerHTML=`<div class="sfps-modal"><div class="sfps-modal-head"><div><h3>${esc(title)}</h3></div><button class="sfps-modal-close" type="button" onclick="closeSFPSModal()">×</button></div><div class="sfps-modal-body">${body}</div><div class="sfps-modal-actions">${actions}</div></div>`;document.body.appendChild(m)}

async function parentIds(){
 setTitle('Parent IDs','Developer-only parent and linked student account creation');
 if(!me.is_developer) throw new Error('Developer access required.');
 const dir=await api('/api/developer-console/directory');
 const parents=(dir.users||[]).filter(u=>u.role==='parent');
 cards({parents:parents.length,linkedStudents:(dir.students||[]).filter(s=>s.parent_user_id).length});
 $('tableArea').innerHTML=`<div class="panel-head"><div><h2>Parent ID Registry</h2><p>Create Developer-issued Parent IDs with up to 5 linked Student IDs.</p></div><button class="primary" onclick="openParentCreateModal()">+ Create</button></div><div class="notice"><b>Developer controlled</b><div>Parent accounts cannot be self-created. Each Parent ID is issued here with the linked student details.</div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Parent</th><th>Parent ID</th><th>WhatsApp</th><th>Students</th></tr></thead><tbody>${parents.map(p=>{const ss=(dir.students||[]).filter(s=>Number(s.parent_user_id)===Number(p.id));return `<tr><td><strong>${esc(p.name)}</strong></td><td>${esc(p.uid)}</td><td>${esc(p.whatsapp_no||'—')}</td><td>${ss.length}/5 · ${ss.map(s=>esc(s.name)).join(', ')||'—'}</td></tr>`}).join('')||'<tr><td colspan="4"><div class="empty">No Parent IDs created.</div></td></tr>'}</tbody></table></div>`;
 $('announcements').innerHTML='<div class="notice"><b>Parent account policy</b><div>Parents receive only the ID and password issued by a Developer.</div></div>';
}
function closeSFPSModal(){const m=$('sfpsModal');if(m)m.remove()}
function openParentCreateModal(){
 const classes=sfpsClassesCache||[];
 const cls=classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');
 const student=(i)=>`<div class="parent-student-card"><div class="modal-section-title">Student ${i+1}</div><div class="form-grid"><label>Name<input name="studentName" required placeholder="Student name"></label><label>Student ID<input name="studentUid" required placeholder="student@id"></label><label>Password<input name="studentPassword" required minlength="8" type="password" placeholder="Developer-issued password"></label><label>Age<input name="studentAge" required min="2" max="25" type="number"></label><label>Class<select name="studentClass" required>${cls}</select></label><label>Roll No.<input name="studentRoll" type="number" min="1"></label><label class="file-field">Student Image<input name="studentImage" required type="file" accept="image/jpeg,image/png,image/webp,image/gif"></label></div></div>`;
 const modal=document.createElement('div');modal.id='sfpsModal';modal.className='sfps-modal-backdrop';modal.innerHTML=`<div class="sfps-modal sfps-modal-large"><div class="sfps-modal-head"><div><h3>Create Parent ID</h3><p>Developer-only · Maximum 5 students</p></div><button class="sfps-modal-close" type="button" onclick="closeSFPSModal()">×</button></div><form id="parentCreateForm"><div class="form-grid"><label>Parent Name<input name="parentName" required placeholder="Parent full name"></label><label>Parent ID<input name="parentUid" required placeholder="parent@id"></label><label>Password<input name="parentPassword" required minlength="8" type="password" placeholder="Developer-issued password"></label><label>WhatsApp No.<input name="whatsappNo" required placeholder="+91..."></label><label>Parent Age<input name="parentAge" required min="18" max="120" type="number"></label><label class="file-field">Parent Image<input name="parentImage" required type="file" accept="image/jpeg,image/png,image/webp,image/gif"></label></div><div id="parentStudents">${student(1)}</div><div class="modal-inline-actions"><button class="secondary" type="button" onclick="addParentStudentForm()" id="addParentStudentBtn">+ Add another student</button><span id="studentCountHint">1 / 5 students</span></div><div class="sfps-modal-actions"><button class="secondary" type="button" onclick="closeSFPSModal()">Cancel</button><button class="primary" type="submit">Create Parent ID</button></div><div id="parentCreateStatus" class="modal-status"></div></form></div>`;
 document.body.appendChild(modal); modal.querySelector('#parentCreateForm').addEventListener('submit',submitParentCreate); modal._studentTemplate=student; modal._classes=classes;
}
function addParentStudentForm(){const modal=$('sfpsModal');const box=$('parentStudents');const n=box.querySelectorAll('.parent-student-card').length;if(n>=5)return;box.insertAdjacentHTML('beforeend',modal._studentTemplate(n+1));$('studentCountHint').textContent=`${n+1} / 5 students`;if(n+1>=5)$('addParentStudentBtn').disabled=true}
async function submitParentCreate(e){
 e.preventDefault();const form=e.currentTarget;const status=$('parentCreateStatus');status.textContent='Creating Parent ID…';
 const fd=new FormData(form);const cards=[...form.querySelectorAll('.parent-student-card')];const students=cards.map((card)=>({name:card.querySelector('[name="studentName"]').value,uid:card.querySelector('[name="studentUid"]').value,password:card.querySelector('[name="studentPassword"]').value,age:card.querySelector('[name="studentAge"]').value,classId:card.querySelector('[name="studentClass"]').value,rollNo:card.querySelector('[name="studentRoll"]').value}));
 const images=cards.map(card=>card.querySelector('[name="studentImage"]').files[0]);if(images.some(x=>!x)){status.textContent='Please upload every student image.';return}fd.delete('studentName');fd.delete('studentUid');fd.delete('studentPassword');fd.delete('studentAge');fd.delete('studentClass');fd.delete('studentRoll');fd.delete('studentImage');fd.append('students',JSON.stringify(students));fd.delete('studentImages');images.forEach(x=>fd.append('studentImages',x));
 try{await api('/api/developer-console/parent-account',{method:'POST',body:fd});closeSFPSModal();await parentIds();}catch(err){status.textContent=err.message||'Unable to create Parent ID.'}
}

