async function attendanceControl(){setTitle('Attendance Control','Authorized school-wide attendance controls');const [h,g]=await Promise.all([api('/api/academic/holidays'),api('/api/academic/attendance/global-status')]);const reg=await api('/api/academic/teacher-registry?date='+attendanceDate);const ownerControl=['owner','sub-owner'].includes(me.role);$('cards').innerHTML='';$('tableArea').innerHTML=`<div class="planner-prompt"><h3>Teacher Registry</h3><p>Registry is one record per person per day.</p><button class="primary" onclick="toggleTeacherRegistry(${!reg.enabled})" ${ownerControl?'':'disabled'}>${reg.enabled?'Turn Registry Off':'Turn Registry On'}</button></div><div class="planner-prompt"><h3>All Registers / Attendance</h3><p>Turn all attendance off for a school closure or special announcement.</p><button class="primary" onclick="toggleGlobalAttendance(${!g.off})" ${ownerControl?'':'disabled'}>${g.off?'Turn Attendance Back On':'Turn All Attendance Off'}</button></div><div class="planner-prompt"><h3>Declared Holidays</h3><p>Sunday and declared holidays automatically close attendance.</p><div class="form-grid"><label>Date<input id="holidayDate" type="date"></label><label>Name<input id="holidayName" placeholder="Holiday name"></label></div><button class="secondary" onclick="addHoliday()" ${ownerControl?'':'disabled'}>Declare Holiday</button><div class="table-wrap"><table class="data-table"><tr><th>Date</th><th>Holiday</th></tr>${(h.holidays||[]).map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.name)}</td></tr>`).join('')}</table></div></div>`;$('announcements').innerHTML='<div class="notice"><b>Attendance Control</b><div>Only authorized administrators can change school-wide controls.</div></div>'}
async function toggleTeacherRegistry(enabled){try{await api('/api/academic/teacher-registry/allow',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled})});await attendanceControl()}catch(e){alert(e.message)}}
async function toggleGlobalAttendance(off){try{await api('/api/academic/attendance/global-off',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({off})});await attendanceControl()}catch(e){alert(e.message)}}
async function addHoliday(){try{await api('/api/academic/holidays',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({date:$('holidayDate').value,name:$('holidayName').value})});await attendanceControl()}catch(e){alert(e.message)}}
async function seatPlanner(){setTitle('Seat Planning','AI-assisted classroom seating');const access=await api('/api/seat-planner/access');if(!access.allowed){throw new Error('Seat Planning is not available for this account.')}const [setup,plans]=await Promise.all([api('/api/seat-planner/class-setup'),api('/api/seat-planner/plans')]);cards({classes:13,population:setup.classes.reduce((n,x)=>n+x.population,0),plans:(plans.plans||[]).length});const builder=access.builder?`<div class="planner-prompt"><h3>Classroom setup</h3><p>Capacity and two-side benches.</p><div class="table-wrap"><table class="data-table"><tr><th>Class</th><th>Population</th><th>Capacity</th><th>Two-side benches</th></tr>${setup.classes.map(c=>`<tr><td>${esc(c.class_name)}</td><td>${c.population}</td><td><input class="mini-input class-cap" data-id="${c.class_id}" value="${c.room_capacity}" type="number" min="0"></td><td><input class="mini-input class-benches" data-id="${c.class_id}" value="${c.two_side_benches}" type="number" min="0"></td></tr>`).join('')}</table></div><button class="secondary" onclick="saveClassSetup()">Save classroom setup</button></div><div class="planner-prompt"><h3>Special planning prompt</h3><textarea id="seatPrompt" rows="4" placeholder="Describe the seating function."></textarea><button class="primary" onclick="buildSeatPlan()">Build Seat Plan</button></div>`:'<div class="notice">Viewer access only.</div>';$('tableArea').innerHTML=builder+`<div class="planner-prompt"><h3>Class Population</h3><div class="population-grid">${setup.classes.map(c=>`<div class="population-card"><span>${esc(c.class_name)}</span><strong>${c.population}</strong><small>students</small></div>`).join('')}</div></div><div class="planner-prompt"><h3>Saved Plans</h3>${(plans.plans||[]).map(p=>`<div class="saved-plan"><strong>${esc(p.title)}</strong><a class="secondary" href="/api/seat-planner/plans/${p.id}/pdf" target="_blank">PDF</a></div>`).join('')||'<div class="empty">No plans.</div>'}</div>`;$('announcements').innerHTML='<div class="notice"><b>Seat Planning</b><div>Protected seating constraints remain server-side.</div></div>'}
async function saveClassSetup(){const classes=[...document.querySelectorAll('.class-cap')].map(i=>({classId:Number(i.dataset.id),roomCapacity:Number(i.value),twoSideBenches:Number(document.querySelector(`.class-benches[data-id="${i.dataset.id}"]`).value)}));try{await api('/api/seat-planner/class-setup',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({classes})});await seatPlanner()}catch(e){alert(e.message)}}
async function buildSeatPlan(){const classConfigs=[...document.querySelectorAll('.class-cap')].map(i=>({classId:Number(i.dataset.id),roomCapacity:Number(i.value),twoSideBenches:Number(document.querySelector(`.class-benches[data-id="${i.dataset.id}"]`).value)}));try{await api('/api/seat-planner/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:'SFPS AI Seat Plan',prompt:$('seatPrompt').value,classConfigs})});await seatPlanner()}catch(e){alert(e.message)}}
async function developerConsole(){
 setTitle('Developer Console','Owner-only SFPS administration');
 const [d,w,a,dir]=await Promise.all([api('/api/developer-console/teachers'),api('/api/developer-console/works'),api('/api/developer-console/access'),api('/api/developer-console/directory')]);
 cards({teachers:d.teachers.length,permissions:a.access.length,classes:13,accounts:(dir.users||[]).length+(dir.students||[]).length});
 let html=`<div class="planner-prompt"><h3>Manage Accounts</h3><button class="primary" onclick="createStaff()">+ Add Teacher ID</button><button class="secondary" onclick="parentIds()">+ Parent IDs</button></div>`;
 if(me.is_primary_developer)html+=`<div class="planner-prompt"><h3>Seat Planning Access</h3><p>Only the primary developer can grant or revoke this protected teacher capability.</p><label>Teacher<select id="seatGrantTeacher">${d.teachers.map(t=>`<option value="${esc(t.uid)}">${esc(t.name)}</option>`).join('')}</select></label><button class="primary" onclick="grantSeatAccess(true)">Grant Seat Planning</button><button class="secondary" onclick="grantSeatAccess(false)">Revoke Seat Planning</button></div>`;
 html+=`<div class="planner-prompt"><h3>Teacher Work Access</h3><div class="form-grid"><label>Teacher<select id="dcTeacher">${d.teachers.map(t=>`<option value="${esc(t.uid)}">${esc(t.name)}</option>`).join('')}</select></label><label>Access<select id="dcWork"><option value="__all__">All</option>${w.works.map(x=>`<option value="${esc(x[0])}">${esc(x[1])}</option>`).join('')}</select></label></div><button class="primary" onclick="dcGrant(true)">Grant</button><button class="secondary" onclick="dcGrant(false)">Revoke</button><p class="muted">Custom access can be granted work-by-work. Developer Console itself is never grantable.</p></div><div class="planner-prompt"><h3>Account Directory</h3><div class="table-wrap"><table class="data-table"><tr><th>Type</th><th>Name</th><th>Action</th></tr>${(dir.users||[]).filter(u=>!['owner','sub-owner'].includes(u.role)).map(u=>`<tr><td>${esc(u.role)}</td><td>${esc(u.name)}</td><td>${['teacher','manager'].includes(u.role)?`<button class="secondary" onclick="changeUserPassword(${u.id},'${esc(u.name)}')">Password</button>`:''}<button class="danger" onclick="removeUser(${u.id},'${esc(u.name)}')">Remove</button></td></tr>`).join('')}${(dir.students||[]).map(x=>`<tr><td>student</td><td>${esc(x.name)}</td><td><button class="danger" onclick="removeStudentAdmin(${x.id},'${esc(x.name)}')">Remove</button></td></tr>`).join('')}</table></div></div>`;
 $('tableArea').innerHTML=html;$('announcements').innerHTML='<div class="notice"><b>Administration</b><div>Protected administration controls are available to authorized developers.</div></div>';
}
