async function addParentStudentAdmin(){return parentIds()}
function changeUserPassword(id,name){openSimpleModal('Change Password',`<p>Set a new password for <strong>${esc(name)}</strong>.</p><label>New password<input id="smNewPassword" type="password" minlength="8" required></label>`,`<button class="secondary" type="button" onclick="closeSFPSModal()">Cancel</button><button class="primary" type="button" onclick="submitPasswordChange(${Number(id)})">Save password</button>`)}
async function submitPasswordChange(id){const p=$('smNewPassword')?.value||'';if(p.length<8)return alert('Password must contain at least 8 characters.');try{await api('/api/developer-console/users/'+id+'/password',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:p})});closeSFPSModal();await developerConsole()}catch(e){alert(e.message)}}
async function removeUser(id,name){if(!confirm('Remove '+name+'?'))return;try{await api('/api/developer-console/users/'+id,{method:'DELETE'});await developerConsole()}catch(e){alert(e.message)}}
async function removeStudentAdmin(id,name){if(!confirm('Remove '+name+'?'))return;try{await api('/api/developer-console/students/'+id,{method:'DELETE'});await developerConsole()}catch(e){alert(e.message)}}
async function ytPage(){setTitle('YT · Your Teacher','Family-friendly school AI assistant');$('cards').innerHTML='';$('tableArea').innerHTML=`<div class="planner-prompt"><h2>YT · Your Teacher</h2><p>Ask educational and school-support questions.</p><div id="ytMessages" class="chat-messages"></div><div class="chat-input"><input id="ytInput" placeholder="Ask YT…"><button class="primary" onclick="sendYT()">Send</button></div></div>`;const s=await api('/api/yt/status');$('ytMessages').innerHTML=`<div class="chat-bubble assistant">Hello! I am YT, Your Teacher. ${s.available?'I am ready to help.':'AI is not configured yet.'}</div>`}
async function sendYT(){const input=$('ytInput'),msg=input.value.trim();if(!msg)return;const box=$('ytMessages');box.innerHTML+=`<div class="chat-bubble user">${esc(msg)}</div>`;input.value='';try{const d=await api('/api/yt/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:msg})});box.innerHTML+=`<div class="chat-bubble assistant">${esc(d.reply)}</div>`}catch(e){box.innerHTML+=`<div class="chat-bubble warning">${esc(e.message)}</div>`}}
async function selectLinkedStudent(id){selectedStudentId=id?Number(id):null;await show(currentPage)}
async function parentNotices(){setTitle('Notices','School announcements for your family');const d=await api('/api/academic/announcements');$('cards').innerHTML='';$('tableArea').innerHTML=(d.announcements||[]).map(a=>`<div class="notice"><b>${esc(a.title)}</b><small>${esc(a.created_at||'')}</small><div>${esc(a.message)}</div></div>`).join('')||'<div class="empty">No notices.</div>';$('announcements').innerHTML='<div class="notice"><b>Family notices</b><div>Only school-published notices are shown.</div></div>'}
async function ratings(){setTitle('Teacher Ratings','Share a respectful rating for your teachers');const d=await api('/api/academic/teachers-for-rating');$('cards').innerHTML='';$('tableArea').innerHTML=`<div class="planner-prompt"><h3>Rate a teacher</h3><div class="form-grid"><label>Teacher<select id="ratingTeacher">${(d.teachers||[]).map(t=>`<option value="${esc(t.uid)}">${esc(t.display_name||t.name)}</option>`).join('')}</select></label><label>Stars<select id="ratingValue"><option value="5">★★★★★</option><option value="4">★★★★</option><option value="3">★★★</option><option value="2">★★</option><option value="1">★</option></select></label></div><textarea id="ratingComment" rows="3" placeholder="Optional feedback"></textarea><button class="primary" onclick="saveRating()">Save Rating</button></div><div class="table-wrap"><table class="data-table"><tr><th>Teacher</th><th>Stars</th><th>Comment</th></tr>${(await api('/api/academic/teacher-ratings')).ratings.map(r=>`<tr><td>${esc(r.teacher_name)}</td><td>${'★'.repeat(r.rating)}</td><td>${esc(r.comment||'')}</td></tr>`).join('')||'<tr><td colspan="3"><div class="empty">No ratings yet.</div></td></tr>'}</table></div>`}
async function saveRating(){try{await api('/api/academic/teacher-ratings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({teacherUid:$('ratingTeacher').value,rating:$('ratingValue').value,comment:$('ratingComment').value})});await ratings()}catch(e){alert(e.message)}}
async function show(page){if(activeController)activeController.abort();activeController=new AbortController();currentPage=page;document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.page===page));try{const fn={dashboard,students,teachers,attendance,syllabus,diary:teacherDiary,headTeach,attendanceControl,results,fees,parent:parentAccounts,parentIds,seatPlanner,developerConsole,parentNotices,ratings,yt:ytPage}[page];if(!fn)throw new Error('Unknown section');await fn()}catch(e){if(e?.name==='AbortError')return;renderError(page,e)}}
$('logout').onclick=async()=>{await api('/api/auth/logout',{method:'POST'});location.href='/login.html'};$('mobileMenu').onclick=()=>$('sidebar')?.classList.toggle('open');$('globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.value.trim())show('students')});
(async()=>{try{await getSFPSClasses();const d=await api('/api/auth/me');me=d.user;$('sideUser').textContent=me.display_name||me.name;$('sideRole').textContent=me.role.toUpperCase();$('userBadge').textContent=me.display_name||me.name;nav();await show('dashboard')}catch(e){console.error(e);location.href='/login.html'}})();
